import pandas as pd
import re
from dateutil import parser
from datetime import datetime

file_path = '/data/mixed_units_register.xlsx'
df = pd.read_excel(file_path, sheet_name='Disbursement Register', header=5)

def parse_amount(val):
    if pd.isna(val):
        return 0.0
    s = str(val).strip()
    if s == '' or s == '-' or s.upper() == 'NA':
        return 0.0
    # remove currency symbol and commas
    s = s.replace('₹', '').replace(',', '').strip()
    # match number and optional suffix
    m = re.match(r'^([0-9]*\.?[0-9]+)\s*([a-zA-Z]+)?$', s)
    if not m:
        # try plain numeric
        try:
            return float(s)
        except:
            return 0.0
    num_str, suffix = m.groups()
    try:
        num = float(num_str)
    except:
        return 0.0
    if not suffix:
        return num
    suffix = suffix.lower()
    if suffix in ['l', 'lakh']:
        mult = 100000
    elif suffix in ['cr', 'crore']:
        mult = 10000000
    elif suffix in ['k', 'thousand']:
        mult = 1000
    else:
        mult = 1
    return num * mult

def parse_date(val):
    if pd.isna(val):
        return None
    s = str(val).strip()
    try:
        # dateutil parser with dayfirst
        dt = parser.parse(s, dayfirst=True, fuzzy=False)
        return dt.date()
    except Exception as e:
        # try manual formats
        for fmt in ('%Y-%m-%d', '%d/%m/%Y', '%d/%m/%y', '%d %b %Y', '%d %B %Y', '%-d %b %Y'):
            try:
                return datetime.strptime(s, fmt).date()
            except:
                continue
    return None

df['amount_inr'] = df['Amount'].apply(parse_amount)
df['date_parsed'] = df['Disbursement Date'].apply(parse_date)

# filter
mask_program = df['Programme'].astype(str).str.strip() == 'Maternal & Child Health'
mask_date = df['date_parsed'] >= datetime(2025,4,1).date() and df['date_parsed'] <= datetime(2025,6,30).date()
