start = datetime(2025,4,1).date()
end = datetime(2025,6,30).date()
mask_date = df['date_parsed'].between(start, end, inclusive='both')
filtered = df[mask_program & mask_date]

print('Total rows:', len(df))
print('Filtered rows:', len(filtered))
print(filtered[['Record ID','Disbursement Date','date_parsed','Amount','amount_inr','Programme']])
total = filtered['amount_inr'].sum()
