import pandas as pd
import re
from datetime import datetime
from dateutil import parser

file_path = '/data/mixed_units_register.xlsx'
df = pd.read_excel(file_path, sheet_name='Disbursement Register', header=5)

def parse_amount(val):
    if pd.isna(val):
        return 0.0
    s = str(val).strip()
    if s == '' or s == '-' or s.upper() == 'NA':
        return 0.0
    s = s.replace('₹', '').replace(',', '').strip()
    # extract number and suffix
    m = re.match(r'^([0-9]*\.?[0-9]+)\s*([a-zA-Z]+)?$', s)
    if not m:
        # try plain float
        try:
            return float(s)
        except:
            return 0.0
    num_str, suffix = m.groups()
    try:
        num = float(num_str)
    except:
        return 0.0
    if not suffix:
        return num
    suffix = suffix.lower()
    if suffix in ['l', 'lakh']:
        mult = 100000
    elif suffix in ['cr', 'crore']:
        mult = 10000000
    elif suffix in ['k', 'thousand']:
        mult = 1000
    else:
        mult = 1
    return num * mult

def parse_date(val):
    if pd.isna(val):
        return None
    s = str(val).strip()
    # YYYY-MM-DD
    if re.match(r'^\d{4}-\d{2}-\d{2}$', s):
        y,m,d = s.split('-')
        return datetime(int(y), int(m), int(d)).date()
    # DD/MM/YYYY or DD/MM/YY
    if '/' in s:
        parts = s.split('/')
        if len(parts) == 3:
            d,m,y = parts
            # handle two digit year
            if len(y) == 2:
                y = '20' + y
            return datetime(int(y), int(m), int(d)).date()
    # D Mon YYYY
    for fmt in ('%d %b %Y', '%d %B %Y', '%-d %b %Y', '%-d %B %Y'):
        try:
            return datetime.strptime(s, fmt).date()
        except:
            pass
    # fallback
    try:
        dt = parser.parse(s, dayfirst=True, fuzzy=False)
        return dt.date()
    except:
        return None

df['amount_inr'] = df['Amount'].apply(parse_amount)
df['date_parsed'] = df['Disbursement Date'].apply(parse_date)

start = datetime(2025,4,1).date()
end = datetime(2025,6,30).date()

mask_program = df['Programme'].astype(str).str.strip() == 'Maternal & Child Health'
mask_date = df['date_parsed'].between(start, end)
filtered = df[mask_program & mask_date].copy()

print('Filtered count:', len(filtered))
print(filtered[['Record ID','Disbursement Date','date_parsed','Amount','amount_inr']])
total = filtered['amount_inr'].sum()
print('Total sum:', total)
# also list details
filtered_sorted = filtered.sort_values('date_parsed')
print(filtered_sorted[['Record ID','date_parsed','amount_inr']])
